  var z = 0, sc = 0;
  for (i = 0; i < comps.length; i++) { e[i] = Math.exp(e[i] - m); z += e[i]; }
  for (i = 0; i < comps.length; i++) sc += e[i] / z * (comps[i][0] - x) / v;
