}
var x0 = [];
for (var i = 0; i < N; i++) x0.push(gauss() * sMax * 0.8);
var W = [1, 4];
var traj = [];
for (var g = 0; g < 2; g++) {
  var arr = [];
  for (var i = 0; i < N; i++) {
    var x = x0[i], p = [x];
    for (var s = 0; s < S; s++) {
      var l0 = Math.log(sMax) + (Math.log(sMin) - Math.log(sMax)) * s / S;
      var l1 = Math.log(sMax) + (Math.log(sMin) - Math.log(sMax)) * (s + 1) / S;
      var sg = Math.exp(l0);
      var sc = score(cond, x, sg), su = score(unc, x, sg);
      var gs = sc + (W[g] - 1) * (sc - su);
      x = x + (-sg * sg * gs) * (l1 - l0);
      p.push(x);
    }
    arr.push(p);
  }
  traj.push(arr);
}
function modeOf(xe) {
  var dA = Math.abs(xe - MU_A), dB = Math.abs(xe - MU_B), dC = Math.abs(xe - MU_C);
  if (dA <= dB && dA <= dC) return 0;
  if (dB <= dC) return 1;
  return 2;
}
var cols = ['#0284c7', '#d97706', '#9ca3af'];
var frac = [];
for (var g = 0; g < 2; g++) {
  var c = [0, 0, 0];
  for (var i = 0; i < N; i++) c[modeOf(traj[g][i][S])]++;
  frac.push(c);
}
function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, width, height);
  var tt = time % PERIOD;
  var prog = Math.min(1, tt / ANIM);
  var cur = Math.floor(prog * S);
  var mx = 18, gap = 24;
  var pw = (width - 2 * mx - gap) / 2;
  var top = 52, ph = height - top - 62;
  var xmin = -5, xmax = 5;
  ctx.font = '13px sans-serif';
  ctx.textBaseline = 'alphabetic';
  var stage = cur < S * 0.33 ? 0 : (cur < S * 0.66 ? 1 : 2);
  var names = ['1 · direction shift toward class-weighted mean', '2 · mode separation: weak mode B is lost', '3 · concentration within each mode'];
  var titles = ['No guidance: conditional score (w = 1)', 'CFG: guided score (w = 4)'];
  for (var g = 0; g < 2; g++) {
    var px = mx + g * (pw + gap);
    var X = function (v) { return px + (Math.max(xmin, Math.min(xmax, v)) - xmin) / (xmax - xmin) * pw; };
    var Y = function (s) { return top + s / S * ph; };
    ctx.fillStyle = '#1a1a1d';
    ctx.font = '13px sans-serif';
    ctx.fillText(titles[g], px, top - 26);
    var b = [0, 0.33, 0.66, 1];
    for (var k = 0; k < 3; k++) {
      ctx.fillStyle = (k === stage) ? 'rgba(124,58,237,0.10)' : (k % 2 ? 'rgba(0,0,0,0.025)' : 'rgba(0,0,0,0.0)');
      ctx.fillRect(px, Y(b[k] * S), pw, (b[k + 1] - b[k]) * ph);
    }
    ctx.strokeStyle = '#1a1a1d';
    ctx.lineWidth = 1;
    ctx.strokeRect(px, top, pw, ph);
    ctx.setLineDash([4, 4]);
    var ms = [MU_A, MU_B, MU_C], ml = ['A', 'B', 'C'];
    for (var m = 0; m < 3; m++) {
      ctx.strokeStyle = cols[m];
      ctx.beginPath(); ctx.moveTo(X(ms[m]), top); ctx.lineTo(X(ms[m]), top + ph); ctx.stroke();
      ctx.fillStyle = cols[m];
      ctx.font = '12px sans-serif';
      ctx.fillText(ml[m], X(ms[m]) + 3, top + ph + 14);
    }
    ctx.setLineDash([]);
    ctx.fillStyle = '#1a1a1d';
    ctx.fillText('σ = ' + sMax.toFixed(1), px + 4, top + 14);
    ctx.fillText('σ = ' + sMin.toFixed(2), px + 4, top + ph - 6);
    ctx.save();
    ctx.beginPath(); ctx.rect(px, top, pw, ph); ctx.clip();
    ctx.lineWidth = 1.2;
    for (var i = 0; i < N; i++) {
      var p = traj[g][i];
      var mo = modeOf(p[S]);
      ctx.strokeStyle = mo === 0 ? 'rgba(2,132,199,0.40)' : (mo === 1 ? 'rgba(217,119,6,0.55)' : 'rgba(225,29,72,0.45)');
      ctx.beginPath();
      ctx.moveTo(X(p[0]), Y(0));
      for (var s = 1; s <= cur; s++) ctx.lineTo(X(p[s]), Y(s));
      ctx.stroke();
      ctx.fillStyle = mo === 0 ? '#0284c7' : (mo === 1 ? '#d97706' : '#e11d48');
      ctx.beginPath(); ctx.arc(X(p[cur]), Y(cur), 2.6, 0, 6.2832); ctx.fill();
    }
    ctx.restore();
    ctx.font = '12px sans-serif';
    ctx.fillStyle = '#1a1a1d';
    if (prog >= 1) {
      var f = frac[g];
      ctx.fillText('end: A ' + Math.round(100 * f[0] / N) + '%   B ' + Math.round(100 * f[1] / N) + '%   C ' + Math.round(100 * f[2] / N) + '%', px, top + ph + 32);
    } else {
      var xs = 0;
      for (var i = 0; i < N; i++) xs += traj[g][i][cur];
      ctx.fillText('mean x_t = ' + (xs / N).toFixed(2), px, top + ph + 32);
    }
  }
  var sgc = Math.exp(Math.log(sMax) + (Math.log(sMin) - Math.log(sMax)) * cur / S);
  ctx.font = '13px sans-serif';
  ctx.fillStyle = '#7c3aed';
  ctx.fillText('Stage ' + names[stage], mx, 20);
  ctx.fillStyle = '#1a1a1d';
  ctx.fillText('σ(t) = ' + sgc.toFixed(2) + '   reverse time ↓   score = ∇log p(x|c) + (w−1)(∇log p(x|c) − ∇log p(x))', mx, height - 10);
}
return { draw: draw };

var gamma = 3.0, s0 = 0.45, N = 70;
var mus = [-1.3, 1.3], ws = [0.4, 0.6];
var S = [2.0, 1.0, 0.45, 0.0];
var seed = 12345;
function rnd() { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; var t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function gauss() { var u = rnd() + 1e-9, v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.2831853 * v); }
function dens(x, sig) {
  var v = s0 * s0 + sig * sig, p = 0;
  for (var i = 0; i < 2; i++) { var d = x - mus[i]; p += ws[i] * Math.exp(-d * d / (2 * v)) / Math.sqrt(6.2831853 * v); }
  return p;
}
function score(x, sig) {
  var v = s0 * s0 + sig * sig, num = 0, den = 1e-12;
  for (var i = 0; i < 2; i++) { var d = x - mus[i]; var g = ws[i] * Math.exp(-d * d / (2 * v)); den += g; num += g * (-d / v); }
  return num / den;
}
// precompute trajectories
var jit = [], states = [[]];
var v0 = s0 * s0 + S[0] * S[0];
for (var n = 0; n < N; n++) { jit.push(rnd()); states[0].push(gauss() * Math.sqrt(v0)); }
for (var st = 0; st < 3; st++) {
  var a = S[st], b = S[st + 1];
  var cur = states[states.length - 1].slice(), nx = [];
  for (var n = 0; n < N; n++) {
    var x = cur[n], K = 10;
    for (var k = 0; k < K; k++) { var sg = a + (b - a) * k / K; x += -sg * score(x, sg) * ((b - a) / K); }
    nx.push(x);
  }
  states.push(nx);
  var vv = s0 * s0 + b * b, eps = 0.25 * vv / gamma;
  for (var j = 0; j < 4; j++) {
    var prev = states[states.length - 1], nn = [];
    for (var n = 0; n < N; n++) {
      var y = prev[n] + eps * gamma * score(prev[n], b) + Math.sqrt(2 * eps) * gauss();
      nn.push(Math.max(-4.4, Math.min(4.4, y)));
    }
    states.push(nn);
  }
}
var SEG = 15, SEGT = 0.56, PERIOD = 9;
function ease(u) { return u * u * (3 - 2 * u); }
function draw(ctx, width, height, time, dt) {
  ctx.fillStyle = "#ffffff"; ctx.fillRect(0, 0, width, height);
  var t = time % PERIOD;
  var f = Math.min(t / SEGT, SEG - 1e-6);
  var i = Math.floor(f), u = f - i, e = ease(u);
  if (t >= SEG * SEGT) { i = SEG - 1; u = 1; e = 1; }
  var stage = Math.floor(i / 5), j = i % 5;
  var isPred = j === 0;
  var sa = S[stage], sb = S[stage + 1];
  var sigShow = isPred ? sa + (sb - sa) * e : sb;
  var pad = 36, W = width - 2 * pad;
  var X = function (x) { return pad + (x + 4.5) / 9 * W; };
  var y0 = height * 0.66, sc = height * 0.36 / 3.0;
  // axis
  ctx.strokeStyle = "#1a1a1d"; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(pad, y0); ctx.lineTo(width - pad, y0); ctx.stroke();
  // curves
  var G = 140, ps = [], pg = [], tot = 0;
  for (var g = 0; g <= G; g++) {
    var x = -4.5 + 9 * g / G;
    var d = dens(x, sigShow);
    ps.push(d);
    var q = Math.pow(dens(x, sb), gamma);
    pg.push(q); tot += q;
  }
  tot *= 9 / G;
  ctx.lineWidth = 2;
  ctx.strokeStyle = "#0284c7"; ctx.setLineDash([5, 4]);
  ctx.beginPath();
  for (var g = 0; g <= G; g++) { var px = X(-4.5 + 9 * g / G), py = y0 - Math.min(ps[g] * sc, height * 0.5); if (g === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py); }
  ctx.stroke(); ctx.setLineDash([]);
  var alpha = isPred ? 0.35 + 0.65 * e : 1;
  ctx.globalAlpha = alpha; ctx.strokeStyle = "#7c3aed"; ctx.fillStyle = "rgba(124,58,237,0.10)";
  ctx.beginPath(); ctx.moveTo(X(-4.5), y0);
  for (var g = 0; g <= G; g++) { var px = X(-4.5 + 9 * g / G), py = y0 - Math.min(pg[g] / tot * sc, height * 0.5); ctx.lineTo(px, py); }
  ctx.lineTo(X(4.5), y0); ctx.fill();
  ctx.beginPath();
  for (var g = 0; g <= G; g++) { var px = X(-4.5 + 9 * g / G), py = y0 - Math.min(pg[g] / tot * sc, height * 0.5); if (g === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py); }
