  // particles
  var A = states[i], B = states[i + 1];
  var col = isPred ? "#0284c7" : "#d97706";
  ctx.fillStyle = col;
  for (var n = 0; n < N; n++) {
    var x = A[n] + (B[n] - A[n]) * e;
    var py = y0 + 14 + jit[n] * height * 0.13;
    ctx.globalAlpha = 0.8;
    ctx.beginPath(); ctx.arc(X(Math.max(-4.5, Math.min(4.5, x))), py, 3.3, 0, 6.2832); ctx.fill();
  }
  ctx.globalAlpha = 1;
  // text
  ctx.fillStyle = "#1a1a1d"; ctx.font = "13px sans-serif"; ctx.textAlign = "left";
  ctx.fillText("Classifier-free guidance as predictor-corrector (γ = " + gamma.toFixed(1) + ")", pad, 22);
  ctx.font = "12px sans-serif";
  var msg = isPred
    ? "Predictor: DDIM step σ " + sa.toFixed(2) + " → " + sb.toFixed(2) + "  (x moves along the probability flow of p_σ)"
    : "Corrector: Langevin step " + j + "/4 at σ = " + sb.toFixed(2) + "  x ← x + ε·γ∇log p_σ(x) + √(2ε)·z";
  ctx.fillStyle = isPred ? "#0284c7" : "#d97706";
  ctx.fillText(msg, pad, 42);
  ctx.fillStyle = "#1a1a1d";
  ctx.fillText("round " + (stage + 1) + " of 3,  noise level σ = " + sigShow.toFixed(2), pad, 60);
  var ly = height - 18;
  ctx.fillStyle = "#0284c7"; ctx.fillRect(pad, ly - 8, 16, 3); ctx.fillStyle = "#1a1a1d"; ctx.fillText("p_σ(x)", pad + 22, ly - 3);
  ctx.fillStyle = "#7c3aed"; ctx.fillRect(pad + 90, ly - 8, 16, 3); ctx.fillStyle = "#1a1a1d"; ctx.fillText("p_σ(x)^γ (sharpened, normalised)", pad + 112, ly - 3);
  ctx.fillStyle = "#0284c7"; ctx.beginPath(); ctx.arc(pad + 340, ly - 6, 4, 0, 6.2832); ctx.fill();
  ctx.fillStyle = "#1a1a1d"; ctx.fillText("predictor", pad + 349, ly - 3);
  ctx.fillStyle = "#d97706"; ctx.beginPath(); ctx.arc(pad + 420, ly - 6, 4, 0, 6.2832); ctx.fill();
  ctx.fillStyle = "#1a1a1d"; ctx.fillText("corrector", pad + 429, ly - 3);
  ctx.textAlign = "right"; ctx.fillText("x", width - pad + 8, y0 - 6); ctx.textAlign = "left";
